    H,W=len(g),len(g[0]); S={(i,j) for i in range(H) for j in range(W) if g[i][j]==3}
    r0=min(s[0] for s in S); r1=max(s[0] for s in S); c0=min(s[1] for s in S); c1=max(s[1] for s in S)
    dist=[[99]*W for _ in range(H)]; q=deque(S)
    for s in S: dist[s[0]][s[1]]=0; q.append(s)
    while q:
        i,j=q.popleft()
        for di in(-1,0,1):
            for dj in(-1,0,1):
                ni,nj=i+di,j+dj
                if 0<=ni<H and 0<=nj<W and dist[ni][nj]>dist[i][j]+1:
                    dist[ni][nj]=dist[i][j]+1; q.append((ni,nj))
    out=[row[:] for row in g]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if g[i][j]!=3:
                out[i][j]=4 if (dist[i][j]%2==1) else 2
    return out
